import{_ as p,a0 as n,w as o,s as d,I as e,x as s,a1 as l,A as a,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在终端显示图像缩略图 | LCTT x X-CMD","titleTemplate":false,"description":"如何在终端显示图像缩略图 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在终端显示图像缩略图 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在终端显示图像缩略图 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190102 How To Display Thumbnail Images In Terminal","title":"如何在终端显示图像缩略图","tag":"201902","desc":""},"relativePath":"201902/20190102 How To Display Thumbnail Images In Terminal.md","filePath":"[post].md"}'),h={name:"201902/20190102 How To Display Thumbnail Images In Terminal.md"};function g(c,i,k,u,b,m){const t=n("Link");return o(),d("div",null,[i[26]||(i[26]=e("h1",{id:"如何在终端显示图像缩略图",tabindex:"-1"},[s("如何在终端显示图像缩略图 "),e("a",{class:"header-anchor",href:"#如何在终端显示图像缩略图","aria-label":"Permalink to “如何在终端显示图像缩略图”"},"​")],-1)),i[27]||(i[27]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2019/01/lsix-720x340.png",alt:""})],-1)),e("p",null,[i[1]||(i[1]=s("不久前，我们讨论了 ",-1)),l(t,{href:"https://www.ostechnix.com/how-to-display-images-in-the-terminal/"},{default:a(()=>[...i[0]||(i[0]=[s("Fim",-1)])]),_:1}),i[2]||(i[2]=s("，这是一个轻量级的命令行图像查看器应用程序，用于从命令行显示各种类型的图像，如 bmp、gif、jpeg 和 png 等。今天，我偶然发现了一个名为 ",-1)),i[3]||(i[3]=e("code",null,"lsix",-1)),i[4]||(i[4]=s(" 的类似工具。它类似于类 Unix 系统中的 ",-1)),i[5]||(i[5]=e("code",null,"ls",-1)),i[6]||(i[6]=s(" 命令，但仅适用于图像。",-1)),i[7]||(i[7]=e("code",null,"lsix",-1)),i[8]||(i[8]=s(" 是一个简单的命令行实用程序，旨在使用 Sixel 图形格式在终端中显示缩略图。对于那些想知道的人来说，Sixel 是",-1)),i[9]||(i[9]=e("ruby",null,[s("六像素"),e("rt",null,"six pixels")],-1)),i[10]||(i[10]=s("的缩写，是一种位图图形格式。它使用 ImageMagick，因此几乎所有 imagemagick 支持的文件格式都可以正常工作。",-1))]),i[28]||(i[28]=r('<h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><p>关于 <code>lsix</code> 的功能，我们可以列出如下：</p><ul><li>自动检测你的终端是否支持 Sixel 图形格式。如果你的终端不支持 Sixel，它会通知你启用它。</li><li>自动检测终端背景颜色。它使用终端转义序列来试图找出终端应用程序的前景色和背景色，并清楚地显示缩略图。</li><li>如果目录中有更多图像（通常大于 21 个），<code>lsix</code> 将一次显示这些图像，因此你无需等待创建整个蒙太奇图像（LCTT 译注：拼贴图）。</li><li>可以通过 SSH 工作，因此你可以轻松操作存储在远程 Web 服务器上的图像。</li><li>它支持非位图图形，例如 .svg、.eps、.pdf、.xcf 等。</li><li>用 Bash 编写，适用于几乎所有 Linux 发行版。</li></ul><h3 id="安装-lsix" tabindex="-1">安装 lsix <a class="header-anchor" href="#安装-lsix" aria-label="Permalink to “安装 lsix”">​</a></h3><p>由于 <code>lsix</code> 使用 ImageMagick，请确保已安装它。它在大多数 Linux 发行版的默认软件库中都可用。 例如，在 Arch Linux 及其变体如 Antergos、Manjaro Linux 上，可以使用以下命令安装ImageMagick：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S imagemagick</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install imagemagick</span></span></code></pre></div><p><code>lsix</code> 并不需要安装，因为它只是一个 Bash 脚本。只需要下载它并移动到你的 <code>$PATH</code> 中。就这么简单。</p><p>从该项目的 GitHub 主页下载最新的 <code>lsix</code> 版本。我使用如下命令下载 <code>lsix</code> 归档包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget https://github.com/hackerb9/lsix/archive/master.zip</span></span></code></pre></div><p>提取下载的 zip 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ unzip master.zip</span></span></code></pre></div><p>此命令将所有内容提取到名为 <code>lsix-master</code> 的文件夹中。将 <code>lsix</code> 二进制文件从此目录复制到 <code>$PATH</code> 中，例如 <code>/usr/local/bin/</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp lsix-master/lsix /usr/local/bin/</span></span></code></pre></div><p>最后，使 <code>lsix</code> 二进制文件可执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod +x /usr/local/bin/lsix</span></span></code></pre></div><p>如此，现在是在终端本身显示缩略图的时候了。</p><p>在开始使用 <code>lsix</code> 之前，请确保你的终端支持 Sixel 图形格式。</p><p>开发人员在 vt340 仿真模式下的 Xterm 上开发了 <code>lsix</code>。 然而，他声称 <code>lsix</code> 应该适用于任何Sixel 兼容终端。</p><p>Xterm 支持 Sixel 图形格式，但默认情况下不启用。</p><p>你可以从另外一个终端使用命令来启动一个启用了 Sixel 模式的 Xterm：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xterm -ti vt340</span></span></code></pre></div><p>或者，你可以使 vt340 成为 Xterm 的默认终端类型，如下所述。</p><p>编辑 <code>.Xresources</code> 文件（如果它不可用，只需创建它）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi .Xresources</span></span></code></pre></div><p>添加如下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>xterm*decTerminalID    :   vt340</span></span></code></pre></div><p>按下 <code>ESC</code> 并键入 <code>:wq</code> 以保存并关闭该文件。</p><p>最后，运行如下命令来应用改变：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ xrdb -merge .Xresources</span></span></code></pre></div><p>现在，每次启动 Xterm 就会默认启用 Sixel 图形支持。</p><h3 id="在终端中显示缩略图" tabindex="-1">在终端中显示缩略图 <a class="header-anchor" href="#在终端中显示缩略图" aria-label="Permalink to “在终端中显示缩略图”">​</a></h3><p>启动 Xterm（不要忘记以 vt340 模式启动它）。以下是 Xterm 在我的系统中的样子。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/01/xterm-1.png" alt=""></p><p>就像我已经说过的那样，<code>lsix</code> 非常简单实用。它没有任何命令行选项或配置文件。你所要做的就是将文件的路径作为参数传递，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsix ostechnix/logo.png</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/01/lsix-4.png" alt=""></p><p>如果在没有路径的情况下运行它，它将显示在当前工作目录中的缩略图图像。我在名为 <code>ostechnix</code> 的目录中有几个文件。</p><p>要显示此目录中的缩略图，只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsix</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/01/lsix-1.png" alt=""></p><p>看到了吗？所有文件的缩略图都显示在终端里。</p><p>如果使用 <code>ls</code> 命令，则只能看到文件名，而不是缩略图。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/01/ls-command-1.png" alt=""></p><p>你还可以使用通配符显示特定类型的指定图像或一组图像。</p><p>例如，要显示单个图像，只需提及图像的完整路径，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsix girl.jpg</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/01/lsix-2.png" alt=""></p><p>要显示特定类型的所有图像，例如 PNG，请使用如下所示的通配符。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsix *.png</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2019/01/lsix-3.png" alt=""></p><p>对于 JEPG 类型，命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsix *jpg</span></span></code></pre></div><p>缩略图的显示质量非常好。我以为 <code>lsix</code> 会显示模糊的缩略图。但我错了，缩略图清晰可见，就像在图形图像查看器上一样。</p><p>而且，这一切都是唾手可得。如你所见，<code>lsix</code> 与 <code>ls</code> 命令非常相似，但它仅用于显示缩略图。如果你在工作中处理很多图像，<code>lsix</code> 可能会非常方便。试一试，请在下面的评论部分告诉我们你对此实用程序的看法。如果你知道任何类似的工具，也请提出建议。我将检查并更新本指南。</p><p>更多好东西即将到来。敬请关注！</p><p>干杯!</p><hr>',59)),e("p",null,[i[12]||(i[12]=s("via: ",-1)),l(t,{href:"https://www.ostechnix.com/how-to-display-thumbnail-images-in-terminal/"},{default:a(()=>[...i[11]||(i[11]=[s("https://www.ostechnix.com/how-to-display-thumbnail-images-in-terminal/",-1)])]),_:1})]),e("p",null,[i[17]||(i[17]=s("作者：",-1)),l(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...i[13]||(i[13]=[s("SK",-1)])]),_:1}),i[18]||(i[18]=s(" 选题：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[14]||(i[14]=[s("lujun9972",-1)])]),_:1}),i[19]||(i[19]=s(" 译者：",-1)),l(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[15]||(i[15]=[s("wxy",-1)])]),_:1}),i[20]||(i[20]=s(" 校对：",-1)),l(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[16]||(i[16]=[s("wxy",-1)])]),_:1})]),e("p",null,[i[23]||(i[23]=s("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[21]||(i[21]=[s("LCTT",-1)])]),_:1}),i[24]||(i[24]=s(" 原创编译，",-1)),l(t,{href:"https://linux.cn/"},{default:a(()=>[...i[22]||(i[22]=[s("Linux中国",-1)])]),_:1}),i[25]||(i[25]=s(" 荣誉推出",-1))])])}const w=p(h,[["render",g]]);export{y as __pageData,w as default};
